INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (9, 'ACT001', 'VISITE DES EQUIPEMENTS', '. Sauvegarde des données ATC du 24/02/2026 effectuée.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (10, 'ACT002', 'VISITE DES EQUIPEMENTS', '.Sauvegarde des données ATC du 11/02/2026 effectuée.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (11, 'ACT003', 'VISITE DES EQUIPEMENTS', '.Sauvegarde des données ATC du 15/02/2026 effectuée.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (12, 'ACT004', 'CHAINE RADIO', 'Analyse de l''état des POs, récupération des historiques, logs et courbes de consommation; Modification de la configuration pour supprimer le regroupement des rôles au CCR: ce qui permet de régler le problème des appels figés (sur la position CCR ORG); Analyse des instabilités réseaux en priorité sur le PO CCR EXE, investigations en cours');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (13, 'ACT005', 'TOPSKY', 'Appel du CCR pour signaler problème d''impression(imprimante de strip). Au constat, défaut dce connexion entre la position EXC01 et l''imprimante de strip. Redemarrage du noeud PLC01. Retablissement de la connexion;N°OT 2026047443.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (14, 'ACT006', 'TOPSKY', 'Appel du CCR pour signaler un dysfonctionnement sur les positions FDO et EXC01. Redemarrage du noeud EXC01. N° OT 2026047442.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (15, 'ACT007', 'CADRE GARAGE', 'ARCHIVAGE DES DONNEES DE LA MESSAGERIE,Bon fonctionnement.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (16, 'ACT008', 'FACTURATION', 'Assistance à l''importation des données,à suivre.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (17, 'ACT009', 'QIP/NA', 'Assistance connexion à la messagerie');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (18, 'ACT010', 'PREVI', 'Assistance remplacement de l''imprimance Kyocera 2554 par l''entreprise BUROTIC.Bon fonctionnement au constat.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (19, 'ACT011', 'C/MTO:', 'assistance utilisateur pour connexion à pgi via Forticlient. Au constat, mot de passe Outlook expiré. Réinitialisation du mot de passe. OT n°2026047525.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (20, 'ACT012', 'PC BORNE PGI CAT:', 'Augmentation de la RAM du pc borne pgi du CAT passant de 2 à 4Go');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (21, 'ACT013', 'PAYEUR', 'Configuration de pgi,messagerie et OnDrive.Bon fonctionnement');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (22, 'ACT014', 'SECRETARIAT MTO', 'Connexion à l''imprimante KYOCERA 3554ci.Bon fonctionement.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (23, 'ACT015', 'VISITE DES EQUIPEMENTS', 'Défaut des serveurs d''enregistrement (RECA et RECB). Bon fonctionnement dans l''ensemble,');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (24, 'ACT016', 'PC QIP-NA:', 'dysfonctionnement de son pc suite à un problème d''authentification de compte microsoft Outlook.                                                                                                                                                     mesures palliatives, dépannage de son ancien pc, en attendant la résolution du dysfonctionnemment par la DTI; OT n°2026047493.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (25, 'ACT017', 'TOPSKY', 'Dysfonctionnement des graveurs des serveurs REC 1A et REC 1B.Actions effectuées: - remplacement du graveur du REC 1B.- Aspiration à l''aide d''un souffleur pour le nettoyage des serveurs. Tests de gravure effectué;  OT n°2026047492.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (26, 'ACT018', 'TOPSKY', 'Extraction des fichiers Acars du mois de janvier 2026 à la demande du CU/RSI-MET');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (27, 'ACT019', 'VAISALA :', 'Interpelation des exploitants tour pour manque de données vent normal du seuil 21. Au constat, présence de corbeaux et d''pervier sur le site du GLIDE. Egalement ce manque de données vents est constaté fréquemment les matins du à une présence aviaire. Données revenus sans intervention technique.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (28, 'ACT020', 'BUREAU FACTURATION', 'Interpellation de l''agent facturation de service pour signaler un dysfonctionnement du processus d''importation des factures sur les postes FREDA. Au constat, le lecteur FREDA est déconnecté. Reconnection du lecteur.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (30, 'ACT022', 'CHAINE RADIO', 'Investigations avec INEO sur d''éventuels problèmes réseau sur les Pos. A suivre.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (33, 'ACT025', 'QIP/NA', 'Pose de son ancien PC. Problème de connexion à internet');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (29, 'ACT021', 'TWR', 'Interpellation de la Twr pour signaler défaut de configuration lors de l''impression du strip. Au constat, le trait horizontal après impression n''apparait pas sur le strip. Actions menées: -Nettoyage de la tète d''impression. - Arrèt/Marche du noeud abertwp01li.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (31, 'ACT023', 'PREVI METEO', 'Optimisation du pc borne pgi de la previ-meteo. Migration de win7 à 10(installation de win10, offiice 2016, adobe reader; antivirus kaspersky; 8Go de RAM.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (32, 'ACT024', 'VISITE DES EQUIPEMENTS', 'Pas de sauvegarde des données ATC du 03/02/2026: motif: dysfonctionnement des graveurs des serveurs REC1A et REC1B.');
INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (34, 'ACT026', 'AVIMET', 'Pose du moxa du télémetre des nuages CL31.');
