INSERT INTO public."TABLE_DIM_INTERVENTION" VALUES (37, 'ACT029', 'VISITE DES EQUIPEMENTS', 'Sauvegarde des données ATC du 02/02/2026 effectuée. Bon fonctionnement dans l''ensemble. Bon fonctionnement dans l''ensemble.                                                                                                                                                   Mainentances Préventives Hebdomadaires :                                                                                                                                                                                                                                                                                        -AIMANT( OT 2026047478)                                                                                                                                   - AIVIMET( OT 2026047480)                                                                                                                                           GRAW ABJ(OT 2026047479)                                                                                                                              -GENERATEUR BPMP (OT 202604747482)                                                                                -                                                    Mainentances Préventives Trimiestrielle                                                                                                       -SYNERGIE WEB(OT 2026047481)                                             -                                                                           -SCANSIM(OT  2026047477)');
