INSERT INTO public.staging_ats VALUES (142, 'DAKAR', 'DIAP', 'ABIDJAN', 2022, '2022-10-07', 'ETH934', 'GUCY-DIAP', 'CTR', 'Atterrissage', 'Le CCR de Roberts informe le CCR d’Abidjan qu’il a été entendu le bruit d’une explosion lors du décollage  du vol ETH934 de l’aéroport de Conakry et que l’inspection de piste effectuée a indiqué la présence sur la piste de Conakry de débris de pneus.Informé, le pilote sollicite ainsi une assistance des pompiers pour son atterrissage à Abidjan. ', 'Dysfonctionnement bord', 'Atterrissage avec creuvaison de la 3ème roue du train principal droit   ', '09:24:00', '09:24:00', '19:54:00', '10:30:00', 'mineur', 1, '
INSERT INTO public.staging_ats VALUES (148, 'DAKAR', 'DIAP', 'ABIDJAN', 2022, '2022-10-29', 'VRE9000', 'DIAP-DIAP ', 'CTR', 'Descente', ' Arrêt du LOCALIZER signalée  par VRE9000, TUTSI, DH8D, DIAP/DIAP effectuant des exercices de touch and go sur DIAP.  ', 'NAV Issues', 'Arrêt du LOCALIZER', '09:26:00', '09:26:00', '09:34:00', '00:08:00', 'mineur', 1, '- Maintenance CNS avisée et confirme l''arrêt;
