INSERT INTO public.staging_ats VALUES (36, 'DAKAR', 'DIAP', 'ABIDJAN', 2022, '2022-02-16', 'QTR1423', 'DGAA-DIAP', 'CTR', 'Finale', '    QTR1423, B788, A7BCC, DGAA/DIAP en approche finale procédure ILS Z piste 21, décide à 09h10 de remettre les gaz, cause, perte du signal du LOCALIZER à 09h08.  ', 'NAV Issues', 'Arrêt du LOCALIZER', '09:10:00', '09:10:00', '10:35:00', '01:25:00', 'mineur', 1, '- QTR1423 est instruit de maintenir l''axe de piste et de contacter la 129.1 MHz pour l''exécution d''une nouvelle approche;
